"""Host watchdog, independent of the Rust worker; never runs in the guest."""
import json
import subprocess
import sys
import time
import uuid
import shutil
from pathlib import Path

work=Path('/var/lib/judge-probe/jobs')

def clean_root(token):
    # Names are generated by the trusted runner, never by a submission.
    token=str(uuid.UUID(token))
    directory=work/token
    try:shutil.rmtree(directory)
    except FileNotFoundError:pass


def docker(*args):
    return subprocess.run(['docker', *args], check=True, capture_output=True,
                          text=True, timeout=5).stdout


def reap(all_owned=False):
    ids = docker('ps', '-aq', '--filter', 'label=traojudge.probe=true').split()
    for identifier in ids:
        try:container=json.loads(docker('inspect',identifier))[0]
        except subprocess.CalledProcessError as error:
            if 'no such' in error.stderr.lower():continue
            raise
        expiry = int(container['Config']['Labels'].get('traojudge.expires', '0'))
        if all_owned or time.time() >= expiry:
            if container['State']['Paused']:
                try:docker('unpause',container['Id'])
                except subprocess.CalledProcessError as error:
                    if 'no such' in error.stderr.lower():continue
                    if 'not paused' not in error.stderr.lower():raise
            try:
                docker('rm', '-f', container['Id'])
            except subprocess.CalledProcessError as error:
                if 'no such' not in error.stderr.lower():raise
            token=container['Name'].removeprefix('/judge-probe-')
            clean_root(token)
    # Also reap attempts that stopped during Nix setup, before docker create.
    if work.exists():
        for directory in work.iterdir():
            try:
                marker=directory/'.deadline'
                expiry=float(marker.read_text()) if marker.exists() else directory.stat().st_mtime+30
                if time.time()>=expiry:clean_root(directory.name)
            except (FileNotFoundError,ValueError):continue


if __name__ == '__main__':
    if '--all' in sys.argv:
        reap(True)
        if work.exists():
            for directory in work.iterdir():clean_root(directory.name)
    else:
        while True:
            reap()
            time.sleep(0.5)
